import { groupNum1 } from "../../constants/groups";

import "./Group1.css";

export function Group1() {
  return (
    <div className="mainG1">
      {groupNum1.map((elm) => {
        return (
          <div className="box" key={elm.id}>
            <img src={elm.image} alt="worker" />
            <div className="info">
              <div className="name">
                <h2>{elm.name}</h2>
                <h2>{elm.surname}</h2>
              </div>
              <p>age: {elm.age}</p>
              <p>gender: {elm.gender}</p>
              <p>Profession: {elm.profession}</p>
            </div>
          </div>
        );
      })}
    </div>
  );
}
